<?php
namespace OpenLMS\Controllers;

use OpenLMS\Core\Auth;
use OpenLMS\Core\Csrf;
use OpenLMS\Core\Database;
use OpenLMS\Policies\CoursePolicy;
use OpenLMS\Services\UploadService;

trait LessonLearningTrait
{
    public static function lesson(): void
    {
        Auth::requireAuth();
        $pdo=Database::connection();$user=Auth::user();$id=(int)($_GET['id']??0);$lesson=self::loadLesson($pdo,$id);if(!$lesson)self::notFoundOrDenied();$course=self::loadCourse($pdo,(int)$lesson['course_id']);if(!$course||!CoursePolicy::canViewCourse($course,$user))self::notFoundOrDenied();$canManage=CoursePolicy::canManage($course,$user);
        if(!$canManage && !CoursePolicy::lessonAvailableForStudent($lesson,(int)$user['id'])){http_response_code(403);render_page('Lesson locked','<div class="card empty-state"><h2>Lesson locked</h2><p>Complete the required prerequisite lessons or wait until the scheduled release time.</p><a class="btn" href="'.e(app_url('?r=course&id='.(int)$course['id'])).'">Back to course</a></div>');return;}
        $message=$error=null;

        if($_SERVER['REQUEST_METHOD']==='POST'){
            if(!Csrf::validate($_POST['_csrf']??null))$error='Invalid security token.';
            else{$action=(string)($_POST['action']??'');try{
                if($action==='update_lesson'&&$canManage){
                    $title=trim((string)($_POST['title']??''));if($title==='')throw new \RuntimeException('Lesson title is required.');$status=in_array((string)($_POST['status']??''),['draft','published','archived'],true)?(string)$_POST['status']:$lesson['status'];
                    $format=in_array((string)($_POST['content_format']??'rich'),['rich','markdown'],true)?(string)$_POST['content_format']:'rich';$rawContent=mb_substr(str_replace("\0",'',(string)($_POST['content']??'')),0,100000);$content=$format==='markdown'?$rawContent:sanitize_rich_text($rawContent);$pdo->prepare('UPDATE lessons SET title=?,content=?,content_format=?,objectives=?,instructions=?,duration_minutes=?,status=?,release_at=?,updated_at=? WHERE id=?')->execute([$title,$content,$format,trim((string)($_POST['objectives']??''))?:null,trim((string)($_POST['instructions']??''))?:null,self::positiveIntOrNull($_POST['duration_minutes']??null),$status,utc_datetime_from_input($_POST['release_at']??null),gmdate('Y-m-d H:i:s'),$id]);Auth::audit('lessons.update','Updated lesson '.$title,null,'lesson',$id);$message='Lesson saved.';$lesson=self::loadLesson($pdo,$id);
                }elseif($action==='delete_lesson'&&$canManage){
                    $checks=[['learning_materials','lesson_id'],['lesson_links','lesson_id'],['lesson_progress','lesson_id'],['lesson_prerequisites','lesson_id'],['lesson_prerequisites','prerequisite_lesson_id']];
                    $used=0;foreach($checks as [$table,$column]){$st=$pdo->prepare("SELECT COUNT(*) FROM {$table} WHERE {$column}=?");$st->execute([$id]);$used+=(int)$st->fetchColumn();}
                    if($used>0)throw new \RuntimeException('This lesson already has resources, prerequisites, or student progress. Archive it instead of deleting it.');
                    $courseId=(int)$course['id'];$pdo->prepare('DELETE FROM lessons WHERE id=?')->execute([$id]);Auth::audit('lessons.delete','Deleted empty lesson',null,'course',$courseId);flash_set('success','Lesson deleted.');header('Location: '.app_url('?r=course&id='.$courseId));exit;
                }elseif($action==='upload_material'&&$canManage){[$ok,$result]=UploadService::storeLessonMaterial($id,$_FILES['material']??[]);if(!$ok)$error=(string)$result;else{$message='Learning material uploaded.';Auth::audit('materials.upload','Uploaded lesson material',null,'lesson',$id);}
                }elseif($action==='delete_material'&&$canManage){$mat=self::materialForLesson($pdo,(int)($_POST['material_id']??0),$id);if($mat){UploadService::deleteMaterial($mat);$message='Material removed.';Auth::audit('materials.delete','Deleted lesson material',null,'lesson',$id);}
                }elseif($action==='add_link'&&$canManage){$url=safe_external_url((string)($_POST['url']??''));if(!$url)throw new \RuntimeException('Paste a valid HTTP/HTTPS resource link.');$requestedType=(string)($_POST['link_type']??'auto');$type=lesson_resource_type($url,$requestedType);$title=trim((string)($_POST['title']??''));if($title==='')$title=lesson_resource_title($url,$type);$title=mb_substr($title,0,180);$pdo->prepare('INSERT INTO lesson_links (lesson_id,title,url,link_type,created_at) VALUES (?,?,?,?,?)')->execute([$id,$title,$url,$type,gmdate('Y-m-d H:i:s')]);$message='External resource added.';Auth::audit('materials.link','Added lesson resource link',null,'lesson',$id);
                }elseif($action==='delete_link'&&$canManage){$pdo->prepare('DELETE FROM lesson_links WHERE id=? AND lesson_id=?')->execute([(int)($_POST['link_id']??0),$id]);$message='External resource removed.';
                }elseif($action==='set_prerequisites'&&$canManage){self::savePrerequisites($pdo,$lesson,$course,array_map('intval',(array)($_POST['prerequisites']??[])));$message='Prerequisites updated.';
                }elseif($action==='set_progress'&&!$canManage){$complete=isset($_POST['completed']);self::saveProgress($pdo,(int)$user['id'],$id,$complete?100:0);$message=$complete?'Lesson marked complete.':'Lesson marked incomplete.';
                }elseif($action!=='')$error='You do not have permission for that action.';
            }catch(\Throwable $e){$error=self::friendlyDbError($e,'Unable to update lesson.');}}
        }

        $materials=self::materials($pdo,$id);$links=self::links($pdo,$id);$prereqIds=self::prerequisiteIds($pdo,$id);$courseLessons=self::allLessonsForCourse($pdo,(int)$course['id']);$progress=self::lessonProgress($pdo,(int)$user['id'],$id);[$previous,$next]=self::neighborLessons($pdo,$courseLessons,$id,$user,$canManage);
        ob_start(); ?>
        <div class="crumbs"><a href="<?= e(app_url('?r=subjects')) ?>">Subjects</a><span>›</span><a href="<?= e(app_url('?r=subject&id='.(int)$course['subject_id'])) ?>"><?= e($course['subject_name']) ?></a><span>›</span><a href="<?= e(app_url('?r=course&id='.(int)$course['id'])) ?>"><?= e($course['title']) ?></a><span>›</span><span><?= e($lesson['title']) ?></span></div>
        <?php if($message): ?><div class="alert alert-success"><?= e($message) ?></div><?php endif; ?><?php if($error): ?><div class="alert alert-danger"><?= e($error) ?></div><?php endif; ?>
        <div class="lesson-view-grid"><article class="card lesson-content"><header><span class="badge <?= $lesson['status']==='published'?'badge-ok':'' ?>"><?= e($lesson['status']) ?></span><h1><?= e($lesson['title']) ?></h1><div class="lesson-meta"><?php if($lesson['duration_minutes']): ?><span><?= (int)$lesson['duration_minutes'] ?> min</span><?php endif; ?><?php if($lesson['release_at']): ?><span>Release <?= e(format_app_datetime((string)$lesson['release_at'])) ?> · <?= e(app_timezone()) ?></span><?php endif; ?></div></header>
          <?php if($lesson['objectives']): ?><section class="lesson-callout"><h2>Learning objectives</h2><p><?= nl2br(e($lesson['objectives'])) ?></p></section><?php endif; ?>
          <div class="rich-content"><?= lesson_content_html((string)$lesson['content'],(string)($lesson['content_format']??'rich')) ?></div>
          <?php if($lesson['instructions']): ?><section class="lesson-callout"><h2>Instructions</h2><p><?= nl2br(e($lesson['instructions'])) ?></p></section><?php endif; ?>
          <?php foreach($links as $link): ?><?php $resourceType=(string)$link['link_type'];$preview=lesson_resource_preview_url((string)$link['url'],$resourceType); ?><?php if($resourceType==='video' && $preview): ?><section class="video-card"><h2><?= e($link['title']) ?></h2><div class="video-frame"><iframe src="<?= e($preview) ?>" title="<?= e($link['title']) ?>" loading="lazy" allow="accelerometer; encrypted-media; picture-in-picture" allowfullscreen referrerpolicy="strict-origin-when-cross-origin"></iframe></div></section><?php elseif($resourceType==='video' && preg_match('/\.(?:mp4|webm)(?:\?.*)?$/i',$link['url'])): ?><section class="video-card"><h2><?= e($link['title']) ?></h2><video controls preload="metadata" src="<?= e($link['url']) ?>"></video></section><?php elseif($resourceType==='image'): ?><figure class="lesson-media-card"><img src="<?= e($link['url']) ?>" alt="<?= e($link['title']) ?>" loading="lazy" referrerpolicy="no-referrer"><figcaption><?= e($link['title']) ?></figcaption></figure><?php elseif(in_array($resourceType,['pdf','document'],true) && $preview): ?><section class="document-preview-card"><h2><?= e($link['title']) ?></h2><iframe class="document-frame" src="<?= e($preview) ?>" title="<?= e($link['title']) ?>" loading="lazy" referrerpolicy="strict-origin-when-cross-origin"></iframe><p class="hint">If the provider blocks preview, use Open resource below.</p></section><?php endif; ?><?php endforeach; ?>
          <?php foreach($materials as $m): ?><?php if(str_starts_with((string)$m['mime_type'],'image/')): ?><figure class="lesson-media-card"><img src="<?= e(app_url('?r=material-download&id='.(int)$m['id'].'&inline=1')) ?>" alt="<?= e($m['original_name']) ?>" loading="lazy"><figcaption><?= e($m['original_name']) ?></figcaption></figure><?php elseif(str_starts_with((string)$m['mime_type'],'video/')): ?><section class="video-card"><h2><?= e($m['original_name']) ?></h2><video controls preload="metadata" src="<?= e(app_url('?r=material-download&id='.(int)$m['id'].'&inline=1')) ?>"></video></section><?php endif; ?><?php endforeach; ?>
          <?php if($materials||$links): ?><section class="resource-section"><h2>Resources</h2><div class="resource-list"><?php foreach($materials as $m): ?><div><span class="file-icon">↓</span><span><strong><?= e($m['original_name']) ?></strong><small><?= e($m['mime_type']) ?> · <?= e(self::humanBytes((int)$m['size_bytes'])) ?></small></span><a class="btn btn-small" href="<?= e(app_url('?r=material-download&id='.(int)$m['id'])) ?>">Download</a><?php if($canManage): ?><form method="post" class="inline-form" onsubmit="return confirm('Remove this material?')"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="delete_material"><input type="hidden" name="material_id" value="<?= (int)$m['id'] ?>"><button class="icon-btn danger">×</button></form><?php endif; ?></div><?php endforeach; ?><?php foreach($links as $l): ?><?php $lt=(string)$l['link_type'];$code=match($lt){'video'=>'VID','image'=>'IMG','pdf'=>'PDF','document'=>'DOC',default=>'URL'}; ?><div><span class="file-icon resource-code"><?= e($code) ?></span><span><strong><?= e($l['title']) ?></strong><small><?= e(ucfirst($lt)) ?> · <?= e(lesson_resource_provider((string)$l['url'])) ?></small></span><a class="btn btn-small" href="<?= e($l['url']) ?>" target="_blank" rel="noopener noreferrer">Open resource</a><?php if($canManage): ?><form method="post" class="inline-form"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="delete_link"><input type="hidden" name="link_id" value="<?= (int)$l['id'] ?>"><button class="icon-btn danger">×</button></form><?php endif; ?></div><?php endforeach; ?></div></section><?php endif; ?>
          <?php if(!$canManage): ?><form method="post" class="completion-card"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="set_progress"><label class="completion-check"><input type="checkbox" name="completed" value="1" <?= $progress===100?'checked':'' ?> onchange="this.form.submit()"><span><?= $progress===100?'Completed':'Mark lesson complete' ?></span></label></form><?php endif; ?>
          <nav class="lesson-nav"><?php if($previous): ?><a class="btn" href="<?= e(app_url('?r=lesson&id='.(int)$previous['id'])) ?>">← <?= e($previous['title']) ?></a><?php else: ?><span></span><?php endif; ?><?php if($next): ?><a class="btn btn-primary" href="<?= e(app_url('?r=lesson&id='.(int)$next['id'])) ?>"><?= e($next['title']) ?> →</a><?php endif; ?></nav>
        </article>

        <?php if($canManage): ?><aside class="lesson-editor-stack"><section class="card"><h2>Edit lesson</h2><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="update_lesson"><label>Title<input name="title" value="<?= e($lesson['title']) ?>" required maxlength="180"></label><div class="content-editor" data-content-editor><label>Content format<select name="content_format" data-content-format><option value="rich" <?= ($lesson['content_format']??'rich')==='rich'?'selected':'' ?>>Rich text</option><option value="markdown" <?= ($lesson['content_format']??'rich')==='markdown'?'selected':'' ?>>Markdown</option></select></label><div data-rich-panel><p class="hint">Format lesson text without writing HTML.</p><div class="editor-toolbar" data-editor-toolbar><button type="button" data-editor-command="bold"><strong>B</strong></button><button type="button" data-editor-command="italic"><em>I</em></button><button type="button" data-editor-command="underline"><u>U</u></button><button type="button" data-editor-command="insertUnorderedList">Bullets</button><button type="button" data-editor-command="insertOrderedList">Numbers</button><button type="button" data-editor-block="h2">H2</button><button type="button" data-editor-block="h3">H3</button><button type="button" data-editor-block="blockquote">Quote</button><button type="button" data-editor-link>Link</button><button type="button" data-editor-command="removeFormat">Clear</button></div><div class="rich-editor" contenteditable="true" data-rich-editor><?= ($lesson['content_format']??'rich')==='rich' ? $lesson['content'] : '' ?></div></div><div data-markdown-panel hidden><p class="hint">Markdown supports headings, **bold**, *italic*, lists, links, images, quotes and fenced code blocks.</p><textarea class="markdown-editor" data-markdown-editor rows="14"><?= e(($lesson['content_format']??'rich')==='markdown'?$lesson['content']:'') ?></textarea></div><textarea name="content" data-content-input hidden></textarea></div><label>Learning objectives<textarea name="objectives" rows="3"><?= e($lesson['objectives']) ?></textarea></label><label>Instructions<textarea name="instructions" rows="3"><?= e($lesson['instructions']) ?></textarea></label><div class="form-row"><label>Duration (minutes)<input type="number" name="duration_minutes" min="1" max="1440" value="<?= e($lesson['duration_minutes']) ?>"></label><label>Release at (<?= e(app_timezone()) ?>)<input type="datetime-local" name="release_at" value="<?= e(datetime_input_value($lesson['release_at'])) ?>"></label></div><label>Status<select name="status"><?php foreach(['draft','published','archived'] as $st): ?><option value="<?= $st ?>" <?= $lesson['status']===$st?'selected':'' ?>><?= ucfirst($st) ?></option><?php endforeach; ?></select></label><button class="btn btn-primary">Save lesson</button></form><hr><form method="post" onsubmit="return confirm('Delete this lesson? Only a lesson with no resources, prerequisites, or student progress can be deleted.')"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="delete_lesson"><button class="btn btn-danger" type="submit">Delete empty lesson</button></form></section>
          <section class="card"><h2>Lesson resources</h2><p class="hint">Upload a private file or paste a resource link from Google Drive, Google Docs, OneDrive, Dropbox, YouTube, Vimeo or another HTTPS provider.</p><div class="resource-methods"><div class="resource-subform"><h3>Upload file</h3><p class="hint">PDF, Word, PowerPoint, Excel, image, MP4 and ZIP files are stored privately and checked by file signature.</p><form method="post" enctype="multipart/form-data"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="upload_material"><label>Choose file<input type="file" name="material" required accept=".pdf,.doc,.docx,.ppt,.pptx,.xls,.xlsx,.jpg,.jpeg,.png,.webp,.mp4,.zip"></label><button class="btn">Upload file</button></form></div><div class="resource-subform"><h3>Paste link</h3><p class="hint">Use a share/view link. Public Google Drive/Docs links can preview inside the lesson when the provider permits it.</p><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="add_link"><label>Resource URL<input name="url" type="url" required maxlength="1200" placeholder="https://drive.google.com/..." inputmode="url"></label><label>Title <small>optional</small><input name="title" maxlength="180" placeholder="Auto-generated when empty"></label><label>Type<select name="link_type"><option value="auto">Auto detect</option><option value="video">Video</option><option value="image">Image</option><option value="pdf">PDF</option><option value="document">Document / slides / sheet</option><option value="link">Other link</option></select></label><button class="btn">Add link resource</button></form></div></div></section>
          <section class="card"><h2>Prerequisites</h2><form method="post"><input type="hidden" name="_csrf" value="<?= e(Csrf::token()) ?>"><input type="hidden" name="action" value="set_prerequisites"><div class="checkbox-list"><?php foreach($courseLessons as $l): ?><?php if((int)$l['id']===$id)continue; ?><label><input type="checkbox" name="prerequisites[]" value="<?= (int)$l['id'] ?>" <?= in_array((int)$l['id'],$prereqIds,true)?'checked':'' ?>><span><?= e($l['section_title'].' · '.$l['title']) ?></span></label><?php endforeach; ?></div><button class="btn">Save prerequisites</button></form></section>
        </aside><?php endif; ?></div>
        <?php render_page($lesson['title'],ob_get_clean());
    }

    public static function download(): void
    {
        Auth::requireAuth();$pdo=Database::connection();$user=Auth::user();$id=(int)($_GET['id']??0);
        $stmt=$pdo->prepare('SELECT m.*,l.status lesson_status,l.release_at,cs.course_id,c.teacher_id,c.status course_status,c.subject_id FROM learning_materials m INNER JOIN lessons l ON l.id=m.lesson_id INNER JOIN course_sections cs ON cs.id=l.course_section_id INNER JOIN courses c ON c.id=cs.course_id WHERE m.id=? LIMIT 1');$stmt->execute([$id]);$m=$stmt->fetch();if(!$m)self::notFoundOrDenied();
        $course=self::loadCourse($pdo,(int)$m['course_id']);if(!$course||!CoursePolicy::canViewCourse($course,$user))self::notFoundOrDenied();
        if(!CoursePolicy::canManage($course,$user)){ $lesson=self::loadLesson($pdo,(int)$m['lesson_id']);if(!$lesson||!CoursePolicy::lessonAvailableForStudent($lesson,(int)$user['id']))self::notFoundOrDenied(); }
        $path=UploadService::resolveStoredPath((string)$m['stored_name']);if(!$path||!is_file($path)){http_response_code(404);echo 'File not found.';return;}
        $name=preg_replace('/[\r\n"]+/','_', (string)$m['original_name']);$inline=isset($_GET['inline'])&&$_GET['inline']==='1'&&(str_starts_with((string)$m['mime_type'],'image/')||str_starts_with((string)$m['mime_type'],'video/'));header('Content-Type: '.($inline?(string)$m['mime_type']:'application/octet-stream'));header('X-Content-Type-Options: nosniff');header('Content-Disposition: '.($inline?'inline':'attachment').'; filename="'.addcslashes($name,'"\\').'"');header('Content-Length: '.filesize($path));header('Cache-Control: private, no-store');readfile($path);exit;
    }
}
